// SYNTHETIC ONLY. No client data, credentials, network, LLM or message delivery.

// Fixed historical weeks. The ledger is reset per execution; replay is demonstrated inside it.

const reportingSchedule = {"weekday":"Monday","hour":9,"minute":0,"timezone":"UTC","cron":"0 0 9 * * 1","reportingPeriod":"previous complete Monday-Sunday","active":false};

function createFixtureAdapters(fixture, { failSource = null } = {}) {
  if (![null, 'meta', 'ga4'].includes(failSource)) {
    throw new TypeError('failSource must be meta, ga4 or null');
  }
  // JSON-shaped fixtures also run in n8n's Code sandbox without Node-only globals.
  const copy = (value) => value === undefined ? undefined : JSON.parse(JSON.stringify(value));
  const snapshot = copy(fixture);
  return Object.fromEntries(['meta', 'ga4'].map((source) => [source, {
    read() {
      if (source === failSource) throw new Error('Synthetic source unavailable');
      return copy(snapshot?.[source]);
    },
  }]));
}

function getReportContext(request) {
  const invalid = () => { throw new TypeError('Invalid report request'); };
  if (!request || typeof request !== 'object' || Array.isArray(request)) invalid();
  for (const field of ['agencyId', 'accountId', 'propertyId']) {
    if (typeof request[field] !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(request[field])) invalid();
  }
  if (typeof request.currency !== 'string' || !/^[A-Z]{3}$/.test(request.currency)) invalid();
  if (request.timezone !== 'UTC') invalid();
  function date(value) {
    if (typeof value !== 'string' || !/^20\d{2}-\d{2}-\d{2}$/.test(value)) invalid();
    const parsed = new Date(`${value}T00:00:00Z`);
    if (!Number.isFinite(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== value) invalid();
    return parsed;
  }
  const current = date(request.weekStart);
  const asOf = date(request.asOf);
  if (current.getUTCDay() !== 1) invalid();
  const day = 86_400_000;
  if (asOf.getTime() < current.getTime() + 7 * day) invalid();
  const iso = (offset) => new Date(current.getTime() + offset * day).toISOString().slice(0, 10);
  const days = Array.from({ length: 14 }, (_, i) => iso(i - 7));
  const key = [
    'synthetic-marketing', 'v1', request.agencyId, request.accountId,
    request.propertyId, request.currency, request.timezone, request.weekStart,
  ].join(':');
  return {
    key, agencyId: request.agencyId, accountId: request.accountId,
    propertyId: request.propertyId, currency: request.currency, timezone: 'UTC',
    current: { start: iso(0), end: iso(6) },
    prior: { start: iso(-7), end: iso(-1) },
    days,
  };
}

function normalizeWeeklyMetrics(source, response, context) {
  const invalid = () => { throw new TypeError('Invalid or incomplete synthetic source rows'); };
  const object = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
  if (!['meta', 'ga4'].includes(source) || !object(response)) invalid();
  if (response.synthetic !== true || response.timezone !== 'UTC'
      || response.currency !== context.currency) invalid();
  if (source === 'ga4'
      && (response.propertyId !== context.propertyId || response.accountId !== context.accountId
      || response.trafficScope !== 'synthetic_meta_paid')) invalid();
  const rows = source === 'meta' ? response.data : response.rows;
  // Exactly one row per day, including explicit zero days. Missing is not zero.
  if (!Array.isArray(rows) || rows.length !== 14) invalid();
  const byDate = new Map();
  function count(value) {
    if (!['number', 'string'].includes(typeof value)) invalid();
    const text = String(value);
    if (!/^(0|[1-9]\d{0,9})$/.test(text)) invalid();
    const number = Number(text);
    if (!Number.isSafeInteger(number) || number > 1_000_000_000) invalid();
    return number;
  }
  function cents(value) {
    if (!['number', 'string'].includes(typeof value)) invalid();
    const text = String(value);
    if (!/^(0|[1-9]\d{0,6})(\.\d{1,2})?$/.test(text)) invalid();
    const [whole, fraction = ''] = text.split('.');
    const number = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
    if (number > 100_000_000) invalid();
    return number;
  }
  for (const row of rows) {
    if (!object(row)) invalid();
    let date;
    let metrics;
    if (source === 'meta') {
      date = row.date_start;
      if (row.account_id !== context.accountId || row.date_stop !== date) invalid();
      metrics = {
        spendCents: cents(row.spend), impressions: count(row.impressions), clicks: count(row.clicks),
      };
      if (metrics.clicks > metrics.impressions) invalid();
    } else {
      if (typeof row.date !== 'string' || !/^\d{8}$/.test(row.date)) invalid();
      date = `${row.date.slice(0, 4)}-${row.date.slice(4, 6)}-${row.date.slice(6, 8)}`;
      metrics = {
        sessions: count(row.sessions), keyEvents: count(row.keyEvents),
        revenueCents: cents(row.purchaseRevenue),
      };
    }
    if (!context.days.includes(date) || byDate.has(date)) invalid();
    byDate.set(date, metrics);
  }
  function sum(days) {
    const totals = source === 'meta'
      ? { spendCents: 0, impressions: 0, clicks: 0 }
      : { sessions: 0, keyEvents: 0, revenueCents: 0 };
    for (const date of days) {
      const row = byDate.get(date);
      if (!row) invalid();
      for (const field of Object.keys(totals)) totals[field] += row[field];
    }
    return totals;
  }
  return { prior: sum(context.days.slice(0, 7)), current: sum(context.days.slice(7)) };
}

function weekOverWeek(current, prior) {
  if (![current, prior].every((value) => typeof value === 'number'
      && Number.isFinite(value) && value >= 0 && value <= Number.MAX_SAFE_INTEGER)) {
    throw new TypeError('Metrics must be finite nonnegative safe numbers');
  }
  const absolute = current - prior;
  if (prior === 0) {
    return { absolute, percent: current === 0 ? 0 : null, status: current === 0 ? 'both_zero' : 'prior_zero' };
  }
  const percent = absolute / prior * 100;
  if (!Number.isFinite(percent)) return { absolute, percent: null, status: 'out_of_range' };
  return { absolute, percent: Number(percent.toFixed(2)), status: 'comparable' };
}

function createMarketingReporter({ maxReports = 128 } = {}) {
  if (!Number.isInteger(maxReports) || maxReports < 1 || maxReports > 1024) {
    throw new TypeError('maxReports must be 1-1024');
  }
  const ledger = new Map();
  return function report(request, adapters) {
    let context;
    const base = {
      synthetic: true, mode: 'offline_preview', schedule: { ...reportingSchedule },
      delivery: 'not_sent',
    };
    function failure(code, stage, source, retryable) {
      const messages = {
        INVALID_REQUEST: 'Report identity, UTC dates or completed-week window is invalid.',
        SOURCE_FAILURE: 'A synthetic source read failed; no report was committed.',
        INVALID_ROWS: 'Source rows are invalid or incomplete; no report was committed.',
        REPORT_CONFLICT: 'This report key already has different normalized metrics.',
        LEDGER_FULL: 'Demo ledger is full; no report was committed.',
      };
      return {
        ...base, status: 'failed', reportKey: context?.key ?? null, reports: [],
        alerts: [{
          severity: 'error', code, stage, source, reportKey: context?.key ?? null,
          retryable, message: messages[code], delivery: 'output_only',
        }],
      };
    }
    try {
      context = getReportContext(request);
    } catch {
      return failure('INVALID_REQUEST', 'validation', null, false);
    }
    const weekly = {};
    for (const source of ['meta', 'ga4']) {
      let response;
      try {
        response = adapters[source].read();
      } catch {
        // Never expose adapter exception messages, credentials or raw rows in alerts.
        return failure('SOURCE_FAILURE', 'source_read', source, true);
      }
      try {
        weekly[source] = normalizeWeeklyMetrics(source, response, context);
      } catch {
        return failure('INVALID_ROWS', 'normalization', source, false);
      }
    }
    const prior = { ...weekly.meta.prior, ...weekly.ga4.prior };
    const current = { ...weekly.meta.current, ...weekly.ga4.current };
    const fingerprint = JSON.stringify({ prior, current });
    if (ledger.has(context.key)) {
      if (ledger.get(context.key) !== fingerprint) {
        return failure('REPORT_CONFLICT', 'idempotency', null, false);
      }
      return { ...base, status: 'duplicate', reportKey: context.key, reports: [], alerts: [] };
    }
    if (ledger.size >= maxReports) return failure('LEDGER_FULL', 'idempotency', null, false);
    const changes = Object.fromEntries(
      Object.keys(current).map((metric) => [metric, weekOverWeek(current[metric], prior[metric])]),
    );
    const roundedRatio = (a, b, scale = 1) => b === 0 ? null : Number((a / b * scale).toFixed(2));
    function derived(metrics) {
      return {
        ctrPercent: roundedRatio(metrics.clicks, metrics.impressions, 100),
        cpc: roundedRatio(metrics.spendCents, metrics.clicks, 0.01),
        costPerKeyEvent: roundedRatio(metrics.spendCents, metrics.keyEvents, 0.01),
        revenueToSpend: roundedRatio(metrics.revenueCents, metrics.spendCents),
      };
    }
    const change = (metric) => {
      const value = changes[metric];
      if (value.percent === null) return 'n/a; prior zero';
      return `${value.percent > 0 ? '+' : ''}${value.percent.toFixed(2)}%`;
    };
    const summary = {
      synthetic: true, generator: 'deterministic_template_v1', llmCalled: false,
      lines: [
        `SYNTHETIC | ${context.agencyId}/${context.accountId} | ${context.current.start} to ${context.current.end} (UTC).`,
        `Meta spend ${context.currency} ${(current.spendCents / 100).toFixed(2)} (${change('spendCents')} WoW); clicks ${current.clicks} (${change('clicks')} WoW).`,
        `GA4 scoped sessions ${current.sessions} (${change('sessions')} WoW); key events ${current.keyEvents} (${change('keyEvents')} WoW).`,
        `GA4 scoped revenue ${context.currency} ${(current.revenueCents / 100).toFixed(2)} (${change('revenueCents')} WoW).`,
        'Preview only; inspect attribution and data freshness before any client delivery.',
      ],
    };
    const output = {
      ...base, status: 'report_ready', reportKey: context.key, alerts: [],
      reports: [{
        reportKey: context.key, agencyId: context.agencyId, accountId: context.accountId,
        propertyId: context.propertyId, currency: context.currency, timezone: context.timezone,
        windows: { current: context.current, prior: context.prior },
        metrics: { current, prior }, changes,
        derived: { current: derived(current), prior: derived(prior) }, summary,
      }],
    };
    ledger.set(context.key, fingerprint);
    return output;
  };
}

function estimateCosts({
  agencyCounts = [5, 15, 30],
  weeksPerMonth = 52 / 12,
  inputTokensPerSummary = 1500,
  outputTokensPerSummary = 250,
  inputUsdPerMillionTokens = 1,
  outputUsdPerMillionTokens = 4,
  summaryAttemptMultiplier = 1,
  platformMonthlyUsd = 0,
} = {}) {
  if (!Array.isArray(agencyCounts) || agencyCounts.length < 1 || agencyCounts.length > 10
      || Array.from(agencyCounts).some((n) => !Number.isInteger(n) || n < 1 || n > 1000)
      || new Set(agencyCounts).size !== agencyCounts.length) {
    throw new TypeError('Use 1-10 distinct agency counts, each 1-1000');
  }
  const bounded = (value, min, max) => typeof value === 'number' && Number.isFinite(value)
    && value >= min && value <= max;
  if (!bounded(weeksPerMonth, 1, 5)
      || ![inputTokensPerSummary, outputTokensPerSummary].every(
        (n) => Number.isInteger(n) && bounded(n, 0, 1_000_000),
      )
      || ![inputUsdPerMillionTokens, outputUsdPerMillionTokens, platformMonthlyUsd].every(
        (n) => bounded(n, 0, 1_000_000),
      )
      || !bounded(summaryAttemptMultiplier, 1, 10)) {
    throw new TypeError('Invalid cost assumptions');
  }
  const accountsPerAgency = 6;
  const perSummary = (inputTokensPerSummary * inputUsdPerMillionTokens
    + outputTokensPerSummary * outputUsdPerMillionTokens) / 1_000_000;
  const round = (number) => Number(number.toFixed(6));
  return {
    synthetic: true, currency: 'USD', pricing: 'illustrative_inputs_not_vendor_quotes',
    actualLlmCalls: 0, actualTokenSpendUsd: 0,
    assumptions: {
      accountsPerAgency, summariesPerAccountPerWeek: 1, weeksPerMonth,
      inputTokensPerSummary, outputTokensPerSummary,
      inputUsdPerMillionTokens, outputUsdPerMillionTokens,
      summaryAttemptMultiplier, platformMonthlyUsd,
      workflowExecutionsPerAgencyPerWeek: 1, sourceReadsPerAccountPerWeek: 2,
      platformScope: 'one shared monthly amount per scenario, not per agency',
    },
    excluded: ['taxes', 'labor', 'storage', 'ad spend', 'vendor API fees', 'pagination', 'other LLM calls'],
    perSummaryTokenCostUsd: round(perSummary),
    scenarios: agencyCounts.map((agencies) => {
      const accounts = agencies * accountsPerAgency;
      const monthlySummaries = accounts * weeksPerMonth;
      const monthlyAttempts = monthlySummaries * summaryAttemptMultiplier;
      const tokenMonthlyUsd = monthlyAttempts * perSummary;
      return {
        agencies, adAccounts: accounts, summariesPerWeek: accounts,
        summariesPerMonth: round(monthlySummaries),
        summaryAttemptsPerMonth: round(monthlyAttempts),
        workflowExecutionsPerMonth: round(agencies * weeksPerMonth),
        sourceReadsPerMonth: round(accounts * 2 * weeksPerMonth),
        inputTokensPerMonth: round(monthlyAttempts * inputTokensPerSummary),
        outputTokensPerMonth: round(monthlyAttempts * outputTokensPerSummary),
        tokenMonthlyUsd: round(tokenMonthlyUsd),
        estimatedMonthlyUsd: round(tokenMonthlyUsd + platformMonthlyUsd),
      };
    }),
  };
}

function runSyntheticScenario(fixture, request, scenario = 'happy_path') {
  if (!['happy_path', 'prior_zero', 'source_failure', 'invalid_rows'].includes(scenario)) {
    throw new TypeError('Unknown synthetic scenario');
  }
  const input = JSON.parse(JSON.stringify(fixture));
  if (scenario === 'prior_zero') {
    for (const row of input.meta.data.slice(0, 7)) {
      row.spend = '0.00'; row.impressions = '0'; row.clicks = '0';
    }
    for (const row of input.ga4.rows.slice(0, 7)) {
      row.sessions = '0'; row.keyEvents = '0'; row.purchaseRevenue = '0.00';
    }
  }
  if (scenario === 'invalid_rows') input.meta.data[0].spend = '-1.00';
  const adapters = createFixtureAdapters(input, {
    failSource: scenario === 'source_failure' ? 'ga4' : null,
  });
  const report = createMarketingReporter();
  const firstRun = report(request, adapters);
  return {
    synthetic: true, scenario, firstRun,
    replay: firstRun.status === 'report_ready' ? report(request, adapters) : null,
    costs: estimateCosts(),
  };
}

